def parsePort(text: String): Either[PortError, Int] =
  text.toIntOption.filter(p => p > 0 && p < 65536).toRight(PortError.OutOfRange)

val endpoint = for {
  port <- parsePort(raw)
  host <- resolveHost(hostName)
} yield s"$host:$port"

endpoint match {
  case Right(addr) => bind(addr)
  case Left(err)   => log.error(s"invalid endpoint: $err")
}

